package app.netlog;
import java.nio.file.*;import java.util.*;
public final class Main {
 public static void main(String[] args)throws Exception{if(args.length==0){javafx.application.Application.launch(Dashboard.class,args);return;}Path input=Paths.get(args[0]);long threshold=args.length>1?Long.parseLong(args[1]):1000;String n=input.getFileName().toString().toLowerCase(java.util.Locale.ROOT);java.util.List<Packet> packets;if(n.endsWith(".pcap")||n.endsWith(".pcapng"))packets=new CaptureReader().read(input);else{LogParser.Result r=new LogParser().parse(input);for(String e:r.errors)System.err.println(e);packets=r.packets;}Analyzer.Summary s=new Analyzer().analyze(packets,threshold);System.out.println("Loaded "+s.totalPackets+" packets / "+s.totalBytes+" bytes");System.out.println("By protocol: "+s.byProtocol);System.out.println("By source: "+s.bySource);for(String a:s.alerts)System.out.println("ALERT: "+a);Path data=Paths.get("data");Files.createDirectories(data);new ReportExporter().csv(data.resolve("report.csv"),packets);new ReportExporter().text(data.resolve("report.txt"),s);new PacketBinary().write(data.resolve("packets.dat"),packets);new SessionStore().save(data.resolve("session.ser"),packets,threshold);System.out.println("Wrote data/report.csv, data/report.txt, data/packets.dat, data/session.ser");}
}
